void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 st = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    //background color
    vec3 color = vec3(1.0, 0.91, 0.87);

    vec3 petal_color = vec3(0.9647, 0.4706, 0.5922);
    vec3 outline = vec3(0.8373, 0.4314, 0.6569);
    vec3 stamen_color = vec3(1.0, 0.96, 0.5);

    float r = length(st) * 2.0f;

    float a = atan(st.x, st.y);
    float f = abs(cos(2.5 * a)) * 0.5 + 0.5;
    //combining harmonics and decreasing their amplitude to create a small 
    //stamen
    float f_in = abs(cos(a*2.)*sin(a*2.))*0.04+0.06;
    //petal
    color = mix(color, petal_color, 1.0 - smoothstep(f, f + 0.02, r));
    //outline for contrast
    color = mix(color, outline, (smoothstep(f - 0.07, f, r) - (smoothstep(f, f + 0.006, r))));
    //stamen
    color = mix(color, stamen_color, 1.0 - smoothstep(f_in, f_in + 0.02, r));

    fragColor = vec4(color, 1.0);
}
